{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Immersive sound intensives: group gatherings, private sessions, and booking in {{CITY}}, {{STATE}}. Select your intensity and find the right session." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-mystic">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Solo Sessions</a>
        <a href="/pricing.html">Investment</a>
        <a href="/about.html">Story</a>
        <a href="/faq.html">FAQ</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a href="/contact.html" class="muted">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero">
      <svg class="hero-pattern" viewBox="0 0 800 400" preserveAspectRatio="none" aria-hidden="true">
        <defs>
          <pattern id="p" width="40" height="40" patternUnits="userSpaceOnUse">
            <rect width="40" height="40" fill="#0f1720" />
            <circle cx="20" cy="20" r="6" fill="#072030" />
            <path d="M0 30 C20 10, 20 10, 40 30" stroke="#1a3a4b" stroke-width="2" fill="none"/>
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#p)"></rect>
      </svg>

      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="hero-title">Sound intensives that reshape how you rest</h1>
          <p class="hero-sub">A focused session suite blending tuned bowls, vocal drones, and guided presence. Choose the intensity that maps to your edge.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/events.html">Upcoming Gatherings</a>
          </div>
          <p class="contact-line">Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>

        <aside class="hero-controls" aria-label="session selector">
          <h3>Sound preference mixer</h3>
          <p class="small">Slide your ear toward soft, steady, or immersive — program guidance updates below.</p>
          <div class="mixer" id="sound-mixer">
            <button data-level="gentle" class="mixer-btn active">Gentle</button>
            <button data-level="medium" class="mixer-btn">Medium</button>
            <button data-level="intense" class="mixer-btn">Intense</button>
          </div>

          <div class="recommendations">
            <h4>Recommended format</h4>
            <div id="program-cards" class="cards">
              <!-- JS populates program cards based on mixer -->
            </div>
          </div>
        </aside>
      </div>
    </section>

    <section class="pillars wrap">
      <h2>How we structure a session</h2>
      <div class="grid">
        <div class="pill">
          <h3>Tuned Arrival</h3>
          <p>A gradual tuning of attention: breath cues and low tones to settle the nervous system.</p>
        </div>
        <div class="pill">
          <h3>Layered Resonance</h3>
          <p>Overlapping instruments build a listening field; movement is minimal, attention is cultivated.
          </p>
        </div>
        <div class="pill">
          <h3>Rest Integration</h3>
          <p>We close with gentle grounding and time to orient before leaving the space.</p>
        </div>
      </div>
    </section>

    <section class="myth-truth wrap">
      <h2>Myths vs. Responsible Practice</h2>
      <div class="columns">
        <div>
          <h3>Myth</h3>
          <p>Sound baths are one-size-fits-all and risk-free for everyone.</p>
        </div>
        <div>
          <h3>Truth</h3>
          <p>We adapt intensity and provide alternatives. Certain conditions (e.g., pregnancy, recent head injury, uncontrolled seizures, photosensitive disorders) require consultation or avoidance. If you have medical concerns, check with your provider before attending.</p>
        </div>
      </div>
    </section>

    <section class="case-notes wrap">
      <h2>Proof Gallery</h2>
      <p class="small">Rotating client reflections and affiliations — real responses, vetted sources.</p>

      <div class="proof">
        <div class="testimonials" id="testimonials">
          <article class="testimonial active" data-id="1">
            <blockquote>"A dense, clarifying pause — I left with sharper focus and less tension."</blockquote>
            <cite>— L., designer</cite>
          </article>
          <article class="testimonial" data-id="2">
            <blockquote>"The deep format was challenging at first but transformational — long-term calm."</blockquote>
            <cite>— R., teacher</cite>
          </article>
          <article class="testimonial" data-id="3">
            <blockquote>"Gentle work that reached places I didn’t expect. Excellent guidance."</blockquote>
            <cite>— K., nurse</cite>
          </article>
        </div>

        <div class="badges" id="badges">
          <button class="badge" data-tooltip="Local wellness collective partner">Wellness Collective</button>
          <button class="badge" data-tooltip="Featured in regional lifestyle magazine">Harbor Life</button>
          <button class="badge" data-tooltip="Graduate of advanced sound training program">Resonance Institute</button>
        </div>
      </div>
    </section>

    <section class="faq wrap">
      <h2>Quick Questions</h2>
      <details>
        <summary>What should I bring?</summary>
        <p>Comfortable layers, a mat, and an open willingness. We provide bolsters and blankets if needed.</p>
      </details>
      <details>
        <summary>Is this suitable for beginners?</summary>
        <p>Yes. We guide from arrival and offer quieter alternatives when requested.</p>
      </details>
      <details>
        <summary>Contraindications?</summary>
        <p>We cannot recommend attendance for people with uncontrolled epilepsy, recent skull/brain injury, or any acute psychiatric crisis. If pregnant or on medical devices, please consult us before booking.</p>
      </details>
    </section>

    <section class="cta wrap">
      <div class="cta-inner">
        <h3>Ready to try a session?</h3>
        <p>Pick an intensity above and reserve a place in the next gathering, or book a private session for focused work.</p>
        <div class="cta-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/book.html">Choose a private session</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="footer-grid">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <p class="muted">Serving {{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        </div>
        <nav>
          <a href="/events.html">Gatherings</a>
          <a href="/private-sessions.html">Solo Sessions</a>
          <a href="/pricing.html">Investment</a>
          <a href="/contact.html">Contact</a>
        </nav>
      </div>
      <p class="muted small">We do not provide medical advice. Attendance is at participant discretion.</p>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
