{"path":"assets/css/styles.css","content":"/* Mystic modern theme */
:root{--bg:#071020;--card:#0f1b26;--muted:#9fb0bf;--accent:#88d1c9;--glass:rgba(255,255,255,0.03);--radius:12px;--max:1100px}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e8f6f5;background:linear-gradient(180deg,var(--bg),#041021);-webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.site-header{border-bottom:1px solid rgba(255,255,255,0.03);backdrop-filter:blur(4px)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{color:var(--accent);font-weight:700;text-decoration:none}
.main-nav a{color:var(--muted);margin-left:18px;text-decoration:none}
.main-nav .cta{background:transparent;border:1px solid var(--accent);padding:8px 12px;border-radius:8px;color:var(--accent);text-decoration:none}
.hero{position:relative;overflow:hidden;padding:40px 0 20px}
.hero-pattern{position:absolute;inset:0;width:100%;height:100%;opacity:0.14}
.hero-inner{display:flex;gap:28px;align-items:flex-start}
.hero-copy{flex:1;color:#dff3f1}
.hero-title{font-size:clamp(28px,4vw,44px);margin:0 0 12px}
.hero-sub{margin:0 0 18px;color:var(--muted)}
.hero-ctas .btn{display:inline-block;margin-right:10px;padding:10px 16px;border-radius:10px;text-decoration:none}
.btn.primary{background:var(--accent);color:#04292a}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted)}
.contact-line{margin-top:12px;color:var(--muted)}
.hero-controls{width:360px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
.mixer{display:flex;gap:8px;margin:12px 0}
.mixer-btn{flex:1;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:var(--glass);color:var(--muted);cursor:pointer}
.mixer-btn.active{background:linear-gradient(90deg,var(--accent),#67c7b8);color:#032f2e}
.recommendations .cards{display:flex;flex-direction:column;gap:10px;margin-top:12px}
.card{background:var(--card);padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.02);color:#dfeff0}
.pillars{padding-top:8px}
.pillars .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.pill{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:10px}
.myth-truth .columns{display:flex;gap:18px}
.case-notes .proof{display:flex;gap:20px;align-items:flex-start}
.testimonials{flex:1;min-height:120px}
.testimonial{display:none;padding:12px}
.testimonial.active{display:block}
.badges{display:flex;flex-direction:column;gap:8px}
.badge{background:transparent;border:1px solid rgba(255,255,255,0.03);color:var(--muted);padding:8px;border-radius:8px;cursor:help}
.badge:focus{outline:2px solid rgba(136,209,201,0.2)}
.faq details{background:var(--card);padding:12px;border-radius:8px;margin-bottom:8px}
.cta-inner{display:flex;align-items:center;justify-content:space-between;gap:20px}
.site-footer{border-top:1px solid rgba(255,255,255,0.03);padding:20px 0;margin-top:30px}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.muted{color:var(--muted)}
.small{font-size:13px;color:var(--muted)}
@media(max-width:900px){
  .hero-inner{flex-direction:column}
  .hero-controls{width:100%}
  .pillars .grid{grid-template-columns:1fr}
  .myth-truth .columns{flex-direction:column}
  .case-notes .proof{flex-direction:column}
  .cta-inner{flex-direction:column}
}
/* Tooltip element created dynamically */
.tooltip{position:fixed;background:#021417;color:#9ff0e8;padding:8px 10px;border-radius:6px;font-size:13px;pointer-events:none;opacity:0;transform:translateY(6px);transition:opacity .18s,transform .18s}
.tooltip.show{opacity:1;transform:translateY(0)}"} 
{"path":"assets/js/main.js","content":"(function(){
  // Sound preference mixer: maps level -> recommended programs
  const programs = {
    gentle: [
      {title:'Drift Suite — Gentle Arrival',duration:'50 min',price:'$28'},
      {title:'Evening Ease — Soft Layers',duration:'60 min',price:'$36'}
    ],
    medium: [
      {title:'Foundry — Mid Resonance',duration:'75 min',price:'$54'},
      {title:'Threaded Field — Mixed Textures',duration:'80 min',price:'$60'}
    ],
    intense: [
      {title:'Deep Forge — Immersive Intensive',duration:'90 min',price:'$95'},
      {title:'Core Release — Extended Immersion',duration:'120 min',price:'$140'}
    ]
  };

  // Mixer UI
  const mixer = document.getElementById('sound-mixer');
  const programCards = document.getElementById('program-cards');
  function renderPrograms(level){
    programCards.innerHTML = '';
    (programs[level]||[]).forEach(p=>{
      const el = document.createElement('div');
      el.className = 'card';
      el.innerHTML = '<strong>'+p.title+'</strong><div class="muted small">'+p.duration+' • '+p.price+'</div><div style="margin-top:8px"><a class="btn ghost" href="/book.html">Book this style</a></div>';
      programCards.appendChild(el);
    });
  }
  // initialize
  renderPrograms('gentle');
  mixer.addEventListener('click',e=>{
    const btn = e.target.closest('.mixer-btn');
    if(!btn) return;
    mixer.querySelectorAll('.mixer-btn').forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    const level = btn.getAttribute('data-level');
    renderPrograms(level);
    // subtle analytics hook (no external calls)
    console.log('mixer:set',level);
  });

  // Proof Gallery rotation
  const testimonials = Array.from(document.querySelectorAll('#testimonials .testimonial'));
  let tIndex = 0;
  function rotateTestimonials(){
    testimonials.forEach((t,i)=>t.classList.toggle('active',i===tIndex));
    tIndex = (tIndex+1) % testimonials.length;
  }
  if(testimonials.length>1){
    setInterval(rotateTestimonials,5000);
  }

  // Badges tooltips
  const badges = Array.from(document.querySelectorAll('#badges .badge'));
  let tooltipEl=null;
  function createTooltip(){
    tooltipEl = document.createElement('div');
    tooltipEl.className='tooltip';
    document.body.appendChild(tooltipEl);
  }
  function showTooltip(text,x,y){
    if(!tooltipEl) createTooltip();
    tooltipEl.textContent = text;
    tooltipEl.style.left = x + 'px';
    tooltipEl.style.top = y + 'px';
    tooltipEl.classList.add('show');
  }
  function hideTooltip(){
    if(tooltipEl) tooltipEl.classList.remove('show');
  }
  badges.forEach(b=>{
    b.addEventListener('mouseenter',e=>{
      const t = b.getAttribute('data-tooltip');
      const rect = b.getBoundingClientRect();
      showTooltip(t,rect.right+12,rect.top);
    });
    b.addEventListener('mouseleave',hideTooltip);
    b.addEventListener('focus',e=>{
      const t = b.getAttribute('data-tooltip');
      const rect = b.getBoundingClientRect();
      showTooltip(t,rect.right+12,rect.top);
    });
    b.addEventListener('blur',hideTooltip);
    // touch alternative
    b.addEventListener('click',e=>{
      const t = b.getAttribute('data-tooltip');
      const rect = b.getBoundingClientRect();
      if(tooltipEl && tooltipEl.classList.contains('show') && tooltipEl.textContent===t){
        hideTooltip();
      } else {
        showTooltip(t,rect.right+12,rect.top);
      }
    });
  });

  // Accessibility: ensure testimonials rotator announces changes
  function announceTestimonials(){
    const live = document.getElementById('testimonials-live');
    if(!live){
      const v = document.createElement('div');
      v.id='testimonials-live';
      v.setAttribute('aria-live','polite');
      v.style.position='absolute';v.style.left='-9999px';v.style.height='1px';v.style.overflow='hidden';
      document.body.appendChild(v);
      v.textContent = testimonials[0] ? testimonials[0].textContent : '';
    }
  }
  announceTestimonials();

  // Lightweight safety notice in console for hosts
  console.log('Sound modules ready — remember to surface contraindications to attendees.');
})();"} 
